/// Convert a single opcode into a human-readable line (debugging aid).
pub fn describe(op: &Opcode) -> String {
    match (op.category(), op.command()) {
        (category::TREE, tree::CREATE_NODE) => {
            format!("TREE:CREATE_NODE id={} type=0x{:04x}", op.a(), op.b() as u16)
        }
        (category::TREE, tree::DELETE_NODE) => format!("TREE:DELETE_NODE id={}", op.a()),
        (category::TREE, tree::INSERT_CHILD) => format!(
            "TREE:INSERT_CHILD parent={} child={} index={}",
            op.a(),
            op.b(),
            op.c()
        ),
        (category::TREE, tree::REMOVE_CHILD) => {
            format!("TREE:REMOVE_CHILD parent={} child={}", op.a(), op.b())
        }
        (category::TREE, tree::MOVE_CHILD) => format!(
            "TREE:MOVE_CHILD parent={} child={} index={}",
            op.a(),
            op.b(),
            op.c()
        ),
        (category::PARAMETER, parameter::SET_PROPERTY) => format!(
            "PARAMETER:SET_PROPERTY id={} prop=0x{:04x} value=0x{:08x}",
            op.a(),
            op.b() as u16,
            op.c()
        ),
        (category::PARAMETER, parameter::SET_TEXT) => {
            format!("PARAMETER:SET_TEXT id={} arenaRef={}", op.a(), op.b())
        }
        (category::PARAMETER, parameter::SET_DESIGN_TOKEN) => format!(
            "PARAMETER:SET_DESIGN_TOKEN pathArenaRef={} valueType=0x{:02x} value=0x{:08x}",
            op.a(),
            op.b() & 0xFF,
            op.c()
        ),
        _ => format!("{:?}", op),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_engine::Engine;
    use pathland_core::{init_memory, Guest, MemoryLayout};
    use pathland_view::{
        assign_ids, text, vstack, Configurable, MediaController, MediaControllerExt, Padding,
        Video, View, ViewExt,
    };
    use std::rc::Rc;

    #[test]
    fn decodes_a_declarative_frame() {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);

        let mut root = vstack![text("ab"), text("cd")]
            .with(|v| {
                v.spacing(4.0);
            })
            .modifiers(Padding(8.0))
            .build();
        assign_ids(&mut root, &mut 1);

        let mut engine = Engine::new();
        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            engine.emit(&root, &mut guest).unwrap();
            guest.end_frame();
        }

        let mut host = pathland_core::Host::new(&mut mem, &layout);
        let frames = host.frames();
        let frame = &frames[0];
        let tree = render_tree_from_frame(frame);

        assert_eq!(tree.nodes.len(), 3);
        let root_node = tree.node(1).unwrap();
        assert_eq!(root_node.component_type, component_type::VSTACK);
        assert_eq!(
            root_node.properties.get(&pathland_core::property_id::SPACING),
            Some(&4.0f32.to_bits())
        );
        let child = tree.node(2).unwrap();
        assert_eq!(child.text.as_deref(), Some("ab"));
        // No layout/rect data is present.
        assert!(!child.properties.contains_key(&pathland_core::property_id::WIDTH));
    }

    /// The Rust view DSL's media kit, end to end into the renderer's tree
    /// (spec/MEDIA.md): a `MediaController` + `attach()` + a `Video` surface emit
    /// a non-visual `MEDIA_CONTROLLER` node carrying its transport, and the
    /// surface is linked to it by `MEDIA_CONTROLLER_ID`.
    #[test]
    fn media_surface_from_the_view_dsl_reaches_the_render_tree() {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);

        let mut engine = Engine::new();
        let player = Rc::new(MediaController::with_source(
            &engine.runtime(),
            "/assets/clip.mp4",
        ));
        player.play();

        let mut root = vstack![player.attach(), Video::new(player.clone())].build();
        assign_ids(&mut root, &mut 1);
        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            engine.emit(&root, &mut guest).unwrap();
            guest.end_frame();
        }

        let mut host = pathland_core::Host::new(&mut mem, &layout);
        let tree = render_tree_from_frame(&host.frames()[0]);

        let controller = tree
            .nodes
            .values()
            .find(|n| n.component_type == component_type::MEDIA_CONTROLLER)
            .expect("the controller's non-visual node");
        // The controller carries the resource and the transport (the app drives
        // playback through them).
        assert_eq!(
            controller.string_property(pathland_core::property_id::MEDIA_SOURCE),
            Some("/assets/clip.mp4")
        );
        assert_eq!(
            controller.u32_property(pathland_core::property_id::PLAYBACK_STATE, 0),
            1,
            "playing was set before the emit"
        );

        let surface = tree
            .nodes
            .values()
            .find(|n| n.component_type == component_type::VIDEO)
            .expect("the video surface");
        assert_eq!(
            surface.u32_property(pathland_core::property_id::MEDIA_CONTROLLER_ID, 0),
            controller.id,
            "the surface points at the controller's node"
        );
    }

    /// `LIST` (`FIT_QUERY`) and `SET_DATE` decode into the shared tree, so the
    /// Qt renderer can measure a fit slot and format a date (spec/PRIMITIVES.md).
    #[test]
    fn decodes_list_and_date_values() {
        // The ring arena entry is `[u32 byteLen][payload]` (Guest::alloc); a
        // LIST payload is `[u32 count][f32 × count]` (spec/OPCODE.md).
        let mut payload = Vec::new();
        payload.extend_from_slice(&2u32.to_le_bytes());
        payload.extend_from_slice(&320.0f32.to_bits().to_le_bytes());
        payload.extend_from_slice(&640.0f32.to_bits().to_le_bytes());
        let mut arena = Vec::new();
        arena.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        arena.extend_from_slice(&payload);

        let ops = [
            Opcode::new(
                category::TREE,
                tree::CREATE_NODE,
                0,
                1,
                component_type::SIZE_THAT_FITS as u32,
                0,
            ),
            Opcode::new(
                category::PARAMETER,
                parameter::SET_PROPERTY,
                0,
                1,
                ((value_type::LIST as u32) << 16)
                    | pathland_core::property_id::FIT_QUERY as u32,
                0,
            ),
            Opcode::new(category::PARAMETER, parameter::SET_DATE, 0, 1, 19_723, 3_600_000),
        ];
        let slots: Vec<u8> = ops.iter().flat_map(|o| o.to_bytes()).collect();
        let frame = Frame::from_parts(&slots, &arena, 0, slots.len());
        let tree = render_tree_from_frame(&frame);

        let node = tree.node(1).unwrap();
        assert_eq!(
            node.list_property(pathland_core::property_id::FIT_QUERY),
            Some([320.0f32, 640.0].as_slice())
        );
        assert_eq!(node.date, Some((19_723, 3_600_000)));
    }

    #[test]
    fn applies_a_delta_frame() {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);

        let mut engine = Engine::new();
        let mut tree = RenderTree::default();

        let mut a = vstack![text("ab")]
            .with(|v| {
                v.spacing(4.0);
            })
            .modifiers(Padding(8.0))
            .build();
        assign_ids(&mut a, &mut 1);
        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            engine.emit(&a, &mut guest).unwrap();
            guest.end_frame();
        }
        {
            let mut host = pathland_core::Host::new(&mut mem, &layout);
            tree.apply_frame(&host.frames()[0]);
        }

        // Delta: spacing 4 -> 12.
        let mut b = vstack![text("ab")]
            .with(|v| {
                v.spacing(12.0);
            })
            .modifiers(Padding(8.0))
            .build();
        assign_ids(&mut b, &mut 1);
        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            engine.emit(&b, &mut guest).unwrap();
            guest.end_frame();
        }
        {
            let mut host = pathland_core::Host::new(&mut mem, &layout);
            tree.apply_frame(&host.frames()[0]);
        }

        assert_eq!(tree.nodes.len(), 2);
        let root = tree.node(1).unwrap();
        assert_eq!(
            root.properties.get(&pathland_core::property_id::SPACING),
            Some(&12.0f32.to_bits())
        );
    }

    #[test]
    fn string_properties_resolve_from_frame() {
        use pathland_core::{Guest, Host, MemoryLayout, init_memory, property_id, value_type};

        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);

        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            guest.create_node(1, component_type::IMAGE).unwrap();
            let ref_src = guest.alloc_str("assets/logo.png").unwrap();
            guest
                .set_property(1, property_id::IMAGE_SOURCE, value_type::STRING, ref_src)
                .unwrap();
            guest.end_frame();
        }
        {
            let mut host = Host::new(&mut mem, &layout);
            let mut tree = RenderTree::default();
            tree.apply_frame(&host.frames()[0]);

            let n = tree.node(1).unwrap();
            assert_eq!(n.component_type, component_type::IMAGE);
            // The STRING property is resolved to its text...
            assert_eq!(
                n.string_property(property_id::IMAGE_SOURCE),
                Some("assets/logo.png")
            );
            // ...and is NOT stored as a raw arena offset in `properties`.
            assert!(!n.properties.contains_key(&property_id::IMAGE_SOURCE));
        }
    }
}

