         int pathRef = core.arenaAlloc(handle, path.getBytes(StandardCharsets.UTF_8));
         int c;
         if (valueType == ValueTypes.STRING) {
             c = core.arenaAlloc(handle, ((String) value).getBytes(StandardCharsets.UTF_8));
         } else {
