         // Dark scheme: the base override falls through when the dark layer is empty.
         tree.set_scheme(Scheme::Dark);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_123456),
