             Opcode::new(category::PARAMETER, parameter::SET_DATE, 0, 1, 19_723, 0),
         ];
         let slots: Vec<u8> = ops.iter().flat_map(|o| o.to_bytes()).collect();
         let frame = Frame::from_parts(&slots, &[], 0, slots.len());

