         router.push("/a");
         assert_eq!(router.path(), "/a");
         assert_eq!(router.depth(), 1);
         router.push("/b");
         assert_eq!(router.depth(), 2);
         router.pop();
         assert_eq!(router.path(), "/a");
         router.navigate("/c");
         assert_eq!(router.path(), "/c");
         router.replace("/d");
         assert_eq!(router.path(), "/d");
         assert_eq!(router.depth(), 1, "replace leaves the back-stack");
     }

