/// The scheme selector contributions. Base rules are `:root`; dark rules
/// apply when the platform is dark (and no override is active) **and**
/// unconditionally under `[data-pathland-scheme="dark"]`. A forced light
/// scheme suppresses the media query via `:not([data-pathland-scheme])`.
fn dark_rule(&self, selector: &str, path: &str, vt: u8, value: &TokenValue) -> String {
    format!(
        "{selector}{{{}:{};}}",
        token_to_css_var(path),
        token_css_value(path, vt, value)
    )
}

/// Render the overrides as CSS rules: base tokens as `:root` rules; dark
/// overrides inside the platform-dark media query (when not forced) and
/// under the forced-dark attribute selector.
///
/// Every base override also populates the forced-dark variable family
/// (`--pl-dark-…`) because the dark resolution layer falls through to base
/// overrides; a dark override is emitted afterwards so it wins.
fn css(&self) -> String {
    let mut css = String::new();
    let mut base_forced_dark = String::new();
    for (path, (vt, value)) in &self.base {
        let name = token_to_css_var(path);
        let v = token_css_value(path, *vt, value);
        css.push_str(&format!(":root{{{name}:{v};}}"));
        base_forced_dark.push_str(&format!(
            ":root{{{}:{v};}}",
            forced_dark_var(path)
        ));
    }
    if !self.dark.is_empty() {
        let dark_rules: String = self
            .dark
            .iter()
            .map(|(path, (vt, value))| self.dark_rule(":root", path, *vt, value))
            .collect();
        let forced_rules: String = self
            .dark
            .iter()
            .map(|(path, (vt, value))| self.dark_rule(":root", path, *vt, value))
            .collect();
        css.push_str(&format!(
            "@media (prefers-color-scheme: dark){{:root:not([data-pathland-scheme]){{{dark_rules}}}}}"
        ));
        css.push_str(&format!(":root[data-pathland-scheme=\"dark\"]{{{forced_rules}}}"));
        // Forced-dark refs: the dark override always wins over the
        // base-derived value emitted above.
        for (path, (vt, value)) in &self.dark {
            css.push_str(&format!(
                ":root{{{}:{};}}",
                forced_dark_var(path),
                token_css_value(path, *vt, value)
            ));
        }
    }
    css.push_str(&base_forced_dark);
    css
}

