Index: lib/rust/crates/pathland-html-golden/src/lib.rs
===================================================================
--- lib/rust/crates/pathland-html-golden/src/lib.rs	
+++ lib/rust/crates/pathland-html-golden/src/lib.rs	
@@ -1,838 +1,874 @@
 //! # pathland-html-golden
 //!
 //! Cross-renderer golden conformance fixtures for the HTML renderers. A small
 //! battery of self-contained `PLPL` batches (opcodes + string section) is
 //! rendered by the canonical Rust SSR renderer (`pathland-render-html`) into
 //! committed fixtures under `lib/typescript/test/fixtures/ssr/`:
 //!
 //! * `{scenario}.plpl` — the batch bytes the TypeScript DOM client decodes
 //!   with `parseBatch` and applies to a fresh DOM (and, for the delta
 //!   scenario, to a hydrated DOM).
 //! * `{scenario}.html` — the canonical `render_fragment` output both renderers
 //!   must reproduce.
 //!
 //! The Rust side (`tests/guard.rs`) and the TypeScript side
 //! (`lib/typescript/test/ssr-conformance.test.ts`) assert the same contract:
 //! the SSR output is the single source of truth, so the two renderers cannot
 //! drift without a test failing.

 use std::io;
 use std::path::{Path, PathBuf};

 use pathland_core::{
     Opcode, category, component_type, property_id, parameter, tree, value_type,
 };
 use pathland_core_transport::encode_frame;
 use pathland_render_html::HtmlRenderer;

 /// The committed fixture directory, resolved relative to this crate so the
 /// emitted files land in the TypeScript test suite.
 pub fn fixture_dir() -> PathBuf {
     Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../typescript/test/fixtures/ssr")
 }

 /// Enum-coded properties are carried as `F32` bits of the enum value (the
 /// renderers decode them via `f32::from_bits`). The codes mirror
 /// `lib/typescript/src/constants.ts` / `spec/MODIFIERS.md`.
 mod enums {
     pub const ALIGN_CENTER: f32 = 1.0;
     pub const SHAPE_ROUNDED_RECTANGLE: f32 = 2.0;
     pub const TOGGLE_STYLE_SWITCH: f32 = 0.0;
 }

 /// A batch builder: opcodes plus a shared string arena. All string references
 /// in the arena are absolute offsets into `strings`, so a base and a delta
 /// batch built from one builder share consistent offsets.
 struct Builder {
     opcodes: Vec<Opcode>,
     strings: Vec<u8>,
 }

 impl Builder {
     fn new() -> Self {
         Self {
             opcodes: Vec::new(),
             strings: Vec::new(),
         }
     }

     /// Append a string to the arena, returning its absolute offset.
     fn string(&mut self, s: &str) -> u32 {
         let offset = self.strings.len() as u32;
         self.strings
             .extend_from_slice(&(s.len() as u32).to_le_bytes());
         self.strings.extend_from_slice(s.as_bytes());
         offset
     }

     fn tree(&mut self, command: u8, a: u32, b: u32, c: u32) {
         self.opcodes
             .push(Opcode::new(category::TREE, command, 0, a, b, c));
     }

     fn style(&mut self, command: u8, a: u32, b: u32, c: u32) {
         self.opcodes
             .push(Opcode::new(category::PARAMETER, command, 0, a, b, c));
     }

     fn create(&mut self, id: u32, component: u16) {
         self.tree(tree::CREATE_NODE, id, component as u32, 0);
     }

     fn insert(&mut self, parent: u32, child: u32) {
         self.tree(tree::INSERT_CHILD, parent, child, pathland_core::APPEND);
     }

     fn set_text(&mut self, id: u32, text: &str) {
         let offset = self.string(text);
         self.style(parameter::SET_TEXT, id, offset, 0);
     }

     /// A `FIT_QUERY`-style `LIST` property: `[u32 count][f32 × count]` in the arena.
     fn set_list_f32(&mut self, id: u32, prop: u16, elements: &[f32]) {
         let offset = self.strings.len() as u32;
         self.strings.extend_from_slice(&(elements.len() as u32).to_le_bytes());
         for element in elements {
             self.strings.extend_from_slice(&element.to_bits().to_le_bytes());
         }
         self.set_prop(id, value_type::LIST, prop, offset);
     }

     fn set_prop(&mut self, id: u32, vt: u8, prop: u16, value: u32) {
         self.style(
             parameter::SET_PROPERTY,
             id,
             ((vt as u32) << 16) | prop as u32,
             value,
         );
     }

     fn set_string(&mut self, id: u32, prop: u16, value: &str) {
         let offset = self.string(value);
         self.set_prop(id, value_type::STRING, prop, offset);
     }

     /// A `DESIGN_TOKEN`-typed property reference: `C` = arena offset of the token path.
     fn set_token_ref(&mut self, id: u32, prop: u16, path: &str) {
         let offset = self.string(path);
         self.set_prop(id, value_type::DESIGN_TOKEN, prop, offset);
     }

     /// A `SET_DESIGN_TOKEN` override: `A` = arena offset of the token path.
     fn set_token(&mut self, path: &str, vt: u8, value: u32) {
         let offset = self.string(path);
         self.style(parameter::SET_DESIGN_TOKEN, offset, vt as u32, value);
     }
 }

 /// A rendered snapshot scenario.
 struct Scenario {
     name: &'static str,
     opcodes: Vec<Opcode>,
     strings: Vec<u8>,
     root: u32,
 }

 /// All full-snapshot scenarios.
 fn scenarios() -> Vec<Scenario> {
     vec![
         counter(),
         form(),
         composite_controls(),
         layout(),
         gridrow(),
         gridtracks(),
         zstack2d(),
         tokens(),
         semantics(),
         icons(),
         sizethatfits(),
         sizethatfits_snapshot(),
         sizethatfits_snapshot_three(),
         media(),
+        native_controls(),
     ]
 }

+fn native_controls() -> Scenario {
+    let mut b = Builder::new();
+    b.create(1, component_type::VSTACK);
+    // PICKER → <select class="pathland-select pathland-control"> + option child.
+    b.create(2, component_type::PICKER);
+    b.create(3, component_type::TEXT);
+    b.insert(2, 3);
+    b.set_text(3, "Red");
+    b.insert(1, 2);
+    // DATE_PICKER → tokenized native date input. (No SET_DATE here: the DOM
+    // client converts the day number in local time, so a fixture with a date
+    // value would be timezone-dependent; the class/token surface is what this
+    // scenario pins.)
+    b.create(4, component_type::DATE_PICKER);
+    b.insert(1, 4);
+    // COLOR_PICKER → tokenized native color input.
+    b.create(5, component_type::COLOR_PICKER);
+    b.set_prop(5, value_type::U32, property_id::COLOR_VALUE, 0x0000FF);
+    b.insert(1, 5);
+    // PROGRESS_VIEW → tokenized native <progress>.
+    b.create(6, component_type::PROGRESS_VIEW);
+    b.set_prop(6, value_type::F32, property_id::PROGRESS, 0.5f32.to_bits());
+    b.set_prop(6, value_type::F32, property_id::MAX_VALUE, 1.0f32.to_bits());
+    b.insert(1, 6);
+    // VIDEO → native <video class="pathland-video" controls>.
+    b.create(7, component_type::VIDEO);
+    b.insert(1, 7);
+    Scenario {
+        name: "native_controls",
+        opcodes: b.opcodes,
+        strings: b.strings,
+        root: 1,
+    }
+}
+
 fn gridtracks() -> Scenario {
     let mut b = Builder::new();
     b.create(1, component_type::GRID);
     b.create(2, component_type::TEXT);
     b.create(3, component_type::TEXT);
     b.insert(1, 2);
     b.insert(1, 3);
     b.set_text(2, "A");
     b.set_text(3, "B");
     // Per-track sizes (spec §grid model): flex / fixed / adaptive → the CSS
     // track template takes precedence over a bare count.
     b.set_string(1, property_id::GRID_TRACKS, "flex,fixed:80,adaptive:50");
     Scenario {
         name: "gridtracks",
         opcodes: b.opcodes,
         strings: b.strings,
         root: 1,
     }
 }

 fn zstack2d() -> Scenario {
     let mut b = Builder::new();
     b.create(1, component_type::ZSTACK);
     b.create(2, component_type::TEXT);
     b.insert(1, 2);
     b.set_text(2, "Layered");
     // topTrailing = 7 → horizontal end × vertical start (2D alignment).
     b.set_prop(1, value_type::F32, property_id::ALIGNMENT, 7f32.to_bits());
     Scenario {
         name: "zstack2d",
         opcodes: b.opcodes,
         strings: b.strings,
         root: 1,
     }
 }

 fn gridrow() -> Scenario {
     let mut b = Builder::new();
     b.create(1, component_type::GRID);
     // Row 0: a 2-cell GRID_ROW; row 1: a short 1-cell GRID_ROW; a bare cell
     // auto-flows into row 2 (widest row = 2 columns).
     b.create(2, component_type::GRID_ROW);
     b.create(3, component_type::TEXT);
     b.create(4, component_type::TEXT);
     b.create(5, component_type::GRID_ROW);
     b.create(6, component_type::TEXT);
     b.create(7, component_type::TEXT);
     b.insert(1, 2);
     b.insert(2, 3);
     b.insert(2, 4);
     b.insert(1, 5);
     b.insert(5, 6);
     b.insert(1, 7);
     b.set_text(3, "A");
     b.set_text(4, "B");
     b.set_text(6, "C");
     b.set_text(7, "D");
     Scenario {
         name: "gridrow",
         opcodes: b.opcodes,
         strings: b.strings,
         root: 1,
     }
 }

 fn media() -> Scenario {
     let mut b = Builder::new();
     b.create(1, component_type::VSTACK);
     b.create(2, component_type::IMAGE);
     b.create(3, component_type::VIDEO);
     b.create(4, component_type::MEDIA_CONTROLLER);
     b.insert(1, 2);
     b.insert(1, 3);
     b.insert(1, 4);
     // Image: absolute asset ref + alt (LABEL) + content-mode Fill → cover + aspect ratio.
     b.set_string(2, property_id::IMAGE_SOURCE, "/_pathland/assets/icons/home.svg");
     b.set_string(2, property_id::LABEL, "Home");
     b.set_prop(2, value_type::F32, property_id::CONTENT_MODE, 1f32.to_bits());
     b.set_prop(2, value_type::F32, property_id::ASPECT_RATIO, 1.5f32.to_bits());
     b.set_prop(2, value_type::F32, property_id::WIDTH, 200f32.to_bits());
     // Video surface: renders its own output; the playback + source belong to the
     // controller (spec/MEDIA.md), so the surface carries no source of its own.
     b.set_prop(3, value_type::F32, property_id::WIDTH, 320f32.to_bits());
     b.set_prop(3, value_type::F32, property_id::HEIGHT, 180f32.to_bits());
     // The media controller: the resource (non-visual, layout-transparent).
     b.set_string(4, property_id::MEDIA_SOURCE, "https://example.com/sample.mp4");
     Scenario {
         name: "media",
         opcodes: b.opcodes,
         strings: b.strings,
         root: 1,
     }
 }

 fn semantics() -> Scenario {
     use pathland_core::role;
